{
  "name": "magpie-deepseek-files",
  "version": "0.5.1",
  "description": "Native Magpie provider plugin: DeepSeek file references and adaptive image budgeting.",
  "type": "module",
  "main": "./index.mjs",
  "exports": "./index.mjs",
  "files": [
    "index.mjs",
    "src/",
    "README.md",
    "LICENSE",
    "assets/",
    "docs/"
  ],
  "scripts": {
    "test": "node --test test/bridge.test.mjs test/image-budget.test.mjs test/opencode-inline.test.mjs",
    "check": "node --check index.mjs && node --check src/bridge.mjs && node --check src/image-budget.mjs && node --check src/cache.mjs && node --check src/paths.mjs && node --check src/models.mjs && node --check src/catalog.mjs && node --check src/compat.mjs && node --check src/opencode-inline.mjs && node --check src/opencode.hooks.mjs",
    "smoke": "node scripts/smoke.mjs"
  },
  "engines": {
    "node": ">=20.9.0"
  },
  "keywords": [
    "magpie",
    "magpie-plugin",
    "opencode-plugin",
    "deepseek",
    "files-api"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/disturbwe/magpie-deepseek-files.git"
  },
  "magpie": {
    "hooks": "./src/opencode.hooks.mjs",
    "icon": "https://raw.githubusercontent.com/disturbwe/magpie-deepseek-files/main/assets/deepseek.svg"
  },
  "dependencies": {
    "sharp": "0.35.5"
  }
}
